// Regenerates src/data/emoji.ts from the emojibase-data package (a dev dependency).
// The generated file is committed, so the app itself needs nothing at runtime.
//   node scripts/gen-emoji.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const load = (p) => JSON.parse(readFileSync(resolve(root, 'node_modules/emojibase-data', p), 'utf8'));
const zh = load('zh/data.json');
const en = new Map(load('en/data.json').map((e) => [e.hexcode, e]));
const zhGroups = load('zh/messages.json').groups;
const enGroups = load('en/messages.json').groups;

// Newer emoji are missing from many systems and would show as empty boxes.
const MAX_VERSION = 15;
const SKIP_GROUPS = new Set([2]); // skin-tone and hair components

const words = (e) => [...new Set([e.label, ...(e.tags ?? [])].map((w) => w.toLowerCase().replace(/[\t\n]/g, ' ')))].join(' ');

const groups = zhGroups
  .filter((g) => !SKIP_GROUPS.has(g.order))
  .map((g) => ({ id: g.order, zh: g.message, en: enGroups.find((x) => x.order === g.order).message }));

const rows = zh
  .filter((e) => e.group !== undefined && !SKIP_GROUPS.has(e.group) && e.version <= MAX_VERSION)
  .sort((a, b) => a.order - b.order)
  .map((e) => [e.group, e.emoji, words(e), words(en.get(e.hexcode) ?? { label: '' })].join('\t'));

const title = (s) => s.replace(/(^|[\s&-])([a-z])/g, (_, a, b) => a + b.toUpperCase());
const out = `// Generated by scripts/gen-emoji.mjs from emojibase-data (MIT). Do not edit by hand.

export interface EmojiGroup {
  id: number;
  zh: string;
  en: string;
}

export const EMOJI_GROUPS: EmojiGroup[] = ${JSON.stringify(groups.map((g) => ({ ...g, en: title(g.en) })), null, 2)};

/** One emoji per line: group id, emoji, Chinese keywords, English keywords (tab separated). */
export const EMOJI_DATA = ${JSON.stringify(rows.join('\n'))};
`;
writeFileSync(resolve(root, 'src/data/emoji.ts'), out);
console.log(`src/data/emoji.ts  ${rows.length} emoji, ${(out.length / 1024).toFixed(0)} kB`);
